const nativeNow = performance.now.bind(performance);
const nativeSetTimeout = globalThis.setTimeout.bind(globalThis);
const nativeClearTimeout = globalThis.clearTimeout.bind(globalThis);

export function realTimeNow(): number {
	return nativeNow();
}

interface TimeApi {
	now(): number;
	schedule(callback: () => void, delay: number): () => void;
}

const realTime: TimeApi = {
	now: realTimeNow,
	schedule: (callback, delay) => {
		const timer = nativeSetTimeout(callback, delay);
		return () => nativeClearTimeout(timer);
	},
};

type StackTraceFormatter = (error: Error, frames: readonly unknown[]) => unknown;

interface StackTraceHost {
	prepareStackTrace?: StackTraceFormatter;
}

interface DiagnosticTime {
	elapsed: number;
	depth: number;
}

const diagnosticTimeKey = Symbol.for('@vscode/component-explorer/diagnosticTime');

function getDiagnosticTime(): DiagnosticTime {
	let owner: { [diagnosticTimeKey]?: DiagnosticTime } = globalThis as typeof globalThis & { [diagnosticTimeKey]?: DiagnosticTime };
	if (typeof window !== 'undefined') {
		let frame: Window = window;
		// Same-origin embedded fixtures must also pause their ancestor's watchdog.
		while (frame.frameElement) {
			frame = frame.parent;
		}
		owner = frame as Window & { [diagnosticTimeKey]?: DiagnosticTime };
	}
	return owner[diagnosticTimeKey] ??= { elapsed: 0, depth: 0 };
}

/** Accounts for synchronous stack formatting without changing its result or error behavior. */
export class DiagnosticClock {
	private _references = 0;
	private _restore: (() => void) | undefined;

	constructor(
		private readonly _host: StackTraceHost,
		private readonly _time: TimeApi,
		private readonly _diagnostics: DiagnosticTime = { elapsed: 0, depth: 0 },
	) {}

	now(): number {
		return this._time.now() - this._diagnostics.elapsed;
	}

	schedule(callback: () => void, delay: number): () => void {
		return this._time.schedule(callback, delay);
	}

	track(): () => void {
		if (this._references++ === 0) {
			const original = this._host.prepareStackTrace;
			if (original) {
				const wrapper: StackTraceFormatter = (error, frames) => {
					const start = this._time.now();
					const outermost = this._diagnostics.depth++ === 0;
					try {
						return Reflect.apply(original, this._host, [error, frames]);
					} finally {
						this._diagnostics.depth--;
						if (outermost) {
							this._diagnostics.elapsed += this._time.now() - start;
						}
					}
				};
				this._host.prepareStackTrace = wrapper;
				this._restore = () => {
					if (this._host.prepareStackTrace === wrapper) {
						this._host.prepareStackTrace = original;
					}
				};
			}
		}
		let disposed = false;
		return () => {
			if (!disposed) {
				disposed = true;
				if (--this._references === 0) {
					this._restore?.();
					this._restore = undefined;
				}
			}
		};
	}
}

const diagnosticClock = new DiagnosticClock(Error as ErrorConstructor & StackTraceHost, realTime, getDiagnosticTime());

export function trackDiagnosticTime(): () => void {
	return diagnosticClock.track();
}

/** A real-time render budget that does not charge synchronous diagnostic formatting. */
export class RenderTimeout {
	readonly promise: Promise<never>;
	private _cancel: (() => void) | undefined;
	private readonly _stopTracking: () => void;
	private _disposed = false;
	private readonly _onAbort = () => this.dispose();

	constructor(
		duration: number,
		private readonly _signal: AbortSignal,
		clock: DiagnosticClock = diagnosticClock,
	) {
		this._stopTracking = clock.track();
		const start = clock.now();
		this.promise = new Promise<never>((_, reject) => {
			const check = () => {
				if (this._disposed) {
					return;
				}
				const remaining = duration - (clock.now() - start);
				if (remaining > 0) {
					this._cancel = clock.schedule(check, remaining);
				} else {
					reject(new Error(`Fixture timed out after ${duration}ms`));
				}
			};
			this._cancel = clock.schedule(check, duration);
		});
		this._signal.addEventListener('abort', this._onAbort);
		if (this._signal.aborted) {
			this.dispose();
		}
	}

	dispose(): void {
		if (!this._disposed) {
			this._disposed = true;
			this._cancel?.();
			this._signal.removeEventListener('abort', this._onAbort);
			this._stopTracking();
		}
	}
}
