import { FixturePath } from '../core/FixturePath.js';
import type { ExplorerTreeNode } from './types.js';

export const FAVORITES_NODE_ID = 'component-explorer-internal:favorites';

export function createFavoriteFixturesTree(
  root: ExplorerTreeNode,
  favoriteNodeIds: ReadonlySet<string>,
): ExplorerTreeNode | undefined {
  const children = collectFavoriteNodes(root.children ?? [], favoriteNodeIds);
  if (children.length === 0) {
    return undefined;
  }

  return {
    id: new FixturePath(FAVORITES_NODE_ID),
    name: 'Favorites',
    type: 'folder',
    children,
    labels: [],
    isFavoritesRoot: true,
  };
}

function collectFavoriteNodes(
  nodes: readonly ExplorerTreeNode[],
  favoriteNodeIds: ReadonlySet<string>,
): readonly ExplorerTreeNode[] {
  const favorites: ExplorerTreeNode[] = [];
  for (const node of nodes) {
    if (favoriteNodeIds.has(node.id.value)) {
      favorites.push(node);
    }
    favorites.push(...collectFavoriteNodes(node.children ?? [], favoriteNodeIds));
  }
  return favorites;
}
